if _C406_ENABLED:
    _C396_SOURCES.update(_C406_ADDED_SOURCES)
c406_submission_agent = agent

# c407: public sale coverage with a market-supply invariant.
# Kaggriculture 1.32.7 ignores $1 sales when adding market inventory.
# Equal sold units can therefore leave unequal public supply after reordering.
# Keep the parent's own execution checks and additionally preserve that supply
# for every surviving public hypothesis. No new orders or field edits.
_C407_ENABLED = True
def _c407_market(farms, privates, market, orders, configuration, own):
    f = _c396_copy.deepcopy(farms)
    p = _c396_copy.deepcopy(privates)
    m = _c396_copy.deepcopy(market)
    state = [_c396_box(observation=_c396_box(farms=f, market=m, private=p[i]),
                      action=dict(market=orders[i])) for i in (0, 1)]
    _C396_ENGINE['_process_market'](state, _c396_box(configuration=configuration))
    cash = [x['money'] for x in f]
    own_farm = dict(f[own])
    own_farm.pop('money')
    # _c396_response already requires result[2:] == base[2:] under all models.
    return cash[own], cash[own]-cash[1-own], p[own], own_farm, m['inventory']
if _C407_ENABLED:
    _c396_market = _c407_market
c407_submission_agent = agent

# c410 development: repairs scoped to executed pickup and overflowing night.
_C410_ENABLED = True
_C410_PICKUP = True
_C410_WORKER = True
_C410_OVERFLOW = True
_C410_NS = _C365_CA_NS
_C410_PARENT = agent
_C410_REPORT = {}
_C410_TELEMETRY = {}


def _c410_feed_need(obs, actor, command):
    step = int(obs['step']); own = int(obs['player'])
    native = _C410_NS['_IMPL'].chassis.players[own]
    tape = _C410_NS['_IMPL'].chassis.routes[2 if step >= 648 else native['route']]
    farm = obs['farms'][own]
    x, y = [farm['farmer'], *farm['hands']][actor]
    visited = set(); need = 0
    moves = {'NORTH': (0, -1), 'SOUTH': (0, 1), 'WEST': (-1, 0), 'EAST': (1, 0)}
    for t in range(step + 1, min(len(tape), (step // 24 + 1) * 24)):
        frame = tape[t]
        commands = [frame.get('farmer') or ['PASS'], *(frame.get('hands') or [])]
        c = commands[actor] if actor < len(commands) and commands[actor] else ['PASS']
        if c[0] == 'DROP' or c[:2] in (['PICKUP', 'WHEAT'], ['PLACE', 'WHEAT']):
            break
        if c[0] in moves:
            dx, dy = moves[c[0]]; x = max(0, min(9, x + dx)); y = max(0, min(9, y + dy))
        if c[0] == 'FEED' and (x, y) not in visited:
            tile = farm['tiles'][y][x]
            if isinstance(tile, dict) and tile.get('animal') and not tile.get('fed_today'):
                visited.add((x, y)); need += 1
    return need


if _C410_ENABLED:
    _C410_NS['_c410_need']=_c410_feed_need
    _C410_NS['_C410_REPORT']=_C410_REPORT
    exec("\ndef _c410_demand(obs, action, farm, private):\n    step=int(obs['step']);own=int(obs['player']);native=_IMPL.chassis.players[own]\n    at=step+1;tape=_IMPL.chassis.routes[2 if at>=648 else native['route']]\n    next_orders=tape[at].get('market') or []\n    horizon=3 if (len(next_orders)>=9 or any(o and o[0]=='HIRE' for o in next_orders)) else 1\n    f,p=_PLANNER_NS['_clone_state'](farm,private)\n    access=((4,4),(5,4),(4,5),(5,5))\n    def hire(orders):\n        positions=[tuple(f['farmer']),*map(tuple,f['hands'])]\n        for o in orders:\n            if o and o[0]=='HIRE':\n                pos=min(access,key=lambda x:(positions.count(x),access.index(x)))\n                positions.append(pos);f['hands'].append(list(pos));p['inventories'].append({})\n    if step%24==23:\n        f['farmer']=[4,4];f['hands']=[];p['inventories']=[{}]\n        for row in f['tiles']:\n            for tile in row:\n                if isinstance(tile,dict) and tile.get('animal'):tile['fed_today']=False\n    else:hire(action.get('market') or [])\n    need=0\n    # Future purchases are intentionally not credited across a crowded hiring\n    # window; reserve actual reachable pickups before that window instead.\n    for t in range(at,min(695,at+horizon,(at//24+1)*24)):\n        route=_IMPL.chassis.routes[2 if t>=648 else native['route']];frame=route[t]\n        commands=[frame.get('farmer') or ['PASS'],*(frame.get('hands') or [])]\n        positions=[f['farmer'],*f['hands']]\n        for actor,c in enumerate(commands[:len(positions)]):\n            if not c:continue\n            if c[:2]==['PICKUP','WHEAT'] and tuple(positions[actor]) in access:\n                future=dict(obs,step=t,farms=list(obs['farms']),private=p)\n                future['farms'][own]=f\n                qty=max(0,int(c[2]) if len(c)>2 else 1)\n                qty=max(qty,_c410_need(future,actor,c)-p['inventories'][actor].get('WHEAT',0))\n                need+=qty;p['inventories'][actor]['WHEAT']=p['inventories'][actor].get('WHEAT',0)+qty\n            else:_PLANNER_NS['_apply_unit_action'](f,p,actor,c,10,t//24,24,100)\n        hire(frame.get('market') or [])\n    # Extra sheep crew has no native-tape pickup. Reserve only its current\n    # unmet feed, counting grain already carried after this turn's fields.\n    for actor,targets in (_V233_STATES.get(own) or {}).get('workers',{}).items():\n        if actor>=len(private['inventories']):continue\n        hungry=sum(isinstance(farm['tiles'][y][x],dict) and farm['tiles'][y][x].get('animal')=='SHEEP' and not farm['tiles'][y][x].get('fed_today') for x,y in targets)\n        need+=max(0,hungry-private['inventories'][actor].get('WHEAT',0))\n    return need\n\ndef _c410_supply(obs,action):\n    step=int(obs['step']);player=int(obs['player']);day=step//24\n    if not 144<=step<695:return action\n    native=_IMPL.chassis.players[player]\n    future=_IMPL.chassis.routes[2 if step+1>=648 else native['route']][step+1]\n    commands=[future.get('farmer') or ['PASS'],*(future.get('hands') or [])]\n    following=_IMPL.chassis.routes[2 if step+2>=648 else native['route']][step+2]\n    next_orders=future.get('market') or []\n    prefund=0\n    if len(next_orders)==10 and not any(o[:2] in (['BUY_PRODUCT','WHEAT'],['SELL','WHEAT']) for o in next_orders):\n        later=[following.get('farmer') or ['PASS'],*(following.get('hands') or [])]\n        demand=lambda cs:sum(max(0,int(c[2]) if len(c)>2 else 1) for c in cs if c[:2]==['PICKUP','WHEAT'])\n        if demand(later):prefund=demand(commands)+demand(later)\n    orders=action.get('market') or []\n    if len(orders)>10 or not _r97_budget(obs,orders):\n        _R97_REPORT['supply_budget_declines']+=1;return action\n    farm,private=_PLANNER_NS['_clone_state'](obs['farms'][player],obs['private'])\n    for actor,c in enumerate([action.get('farmer') or ['PASS'],*(action.get('hands') or [])][:len(private['inventories'])]):\n        _PLANNER_NS['_apply_unit_action'](farm,private,actor,c,10,day,24,100)\n    positions=[tuple(farm['farmer']),*map(tuple,farm['hands'])];night=step%24==23\n    access=((4,4),(5,4),(4,5),(5,5))\n    if night:positions=[(4,4)]\n    else:\n        for order in orders:\n            if order and order[0]=='HIRE':positions.append(min(access,key=lambda p:(positions.count(p),access.index(p))))\n    need=sum(max(0,int(c[2]) if len(c)>2 else 1) for pos,c in zip(positions,commands) if pos in access and c[:2]==['PICKUP','WHEAT'])\n    need=max(need,prefund,_c410_demand(obs,action,farm,private))\n    if not need:return action\n    original_stock,original_buys,_=_r97_market_stock(private['shed'],orders)\n    original_final,original_loss=_r97_delivery(original_stock,private,night)\n    if original_final.get('WHEAT',0)>=need:return action\n    result=copy.deepcopy(action);proposed=result['market'];blocked=False\n    def project(candidate):\n        stock,buys,sales=_r97_market_stock(private['shed'],candidate)\n        final,loss=_r97_delivery(stock,private,night)\n        safe=all(buys.get(i,0)>=q for i,q in original_buys.items()) and all(q<=original_loss.get(item,0) for item,q in loss.items())\n        return final,sales,safe\n    # Hold an existing grain sale first. Preserve all order indices and every\n    # originally funded buy; no extra overnight overflow may be introduced.\n    for index in range(len(proposed)-1,-1,-1):\n        if proposed[index][:2]!=['SELL','WHEAT']:continue\n        final,sales,safe=project(proposed);shortage=max(0,need-final.get('WHEAT',0))\n        if not shortage:break\n        sold=sales.get(index,0)\n        if not sold:continue\n        old=proposed[index][2];proposed[index][2]=max(0,sold-shortage)\n        after,_,safe=project(proposed)\n        if not safe or after.get('WHEAT',0)<=final.get('WHEAT',0):proposed[index][2]=old\n    final,_,safe=project(proposed);shortage=max(0,need-final.get('WHEAT',0))\n    if shortage:\n        last_sale=max((i for i,o in enumerate(proposed) if o[:2]==['SELL','WHEAT']),default=-1)\n        index=next((i for i in range(len(proposed)-1,last_sale,-1) if proposed[i][:2]==['BUY_PRODUCT','WHEAT']),None)\n        if index is not None:proposed[index][2]=max(0,int(proposed[index][2]))+shortage\n        elif len(proposed)<10:proposed.append(['BUY_PRODUCT','WHEAT',shortage])\n        else:_R97_REPORT['supply_slot_declines']+=1;return action\n    final,_,safe=project(proposed)\n    if not safe or final.get('WHEAT',0)<need:\n        _R97_REPORT['supply_capacity_declines']+=1;return action\n    if not _r97_budget(obs,proposed):\n        _R97_REPORT['supply_budget_declines']+=1;return action\n    if prefund:\n        _R97_REPORT['supply_prefund_changes']+=1\n        _R97_REPORT['supply_prefund_units']+=max(0,final.get('WHEAT',0)-original_final.get('WHEAT',0))\n    if step<288:\n        _R97_REPORT['supply_early_changes']+=1\n        _R97_REPORT['supply_early_units']+=max(0,final.get('WHEAT',0)-original_final.get('WHEAT',0))\n    _R97_REPORT['supply_guard_changes']+=1\n    _R97_REPORT['supply_grain_protected']+=final.get('WHEAT',0)-original_final.get('WHEAT',0)\n    _R97_REPORT['supply_buy_units']+=sum(max(0,int(o[2])) for o in proposed if o[:2]==['BUY_PRODUCT','WHEAT'])-sum(max(0,int(o[2])) for o in orders if o[:2]==['BUY_PRODUCT','WHEAT'])\n    return result\ndef _c410_compact_worker(obs,actor,targets):\n    if len(targets)!=6:\n        return _SL_WORKER(obs,actor,targets)\n    farm=obs['farms'][obs['player']];private=obs['private'];step=int(obs['step'])\n    pos=tuple(farm['hands'][actor-1]);inv=private['inventories'][actor]\n    needed=[];hungry=0\n    for target in targets:\n        x,y=target;t=farm['tiles'][y][x]\n        if not isinstance(t,dict) or t.get('animal')!='SHEEP':\n            return _SL_WORKER(obs,actor,targets)\n        if not t['fed_today']:hungry+=1\n        if not t['fed_today'] or not t['cared_today']:needed.append(target)\n    home=_v219_home(pos)\n    if hungry>inv.get('WHEAT',0):\n        if private['shed'].get('WHEAT',0)>0:\n            _C410_REPORT['partial_pickup']+=1\n            return _v219_walk(pos,home) or ['PICKUP','WHEAT',min(hungry-inv.get('WHEAT',0),private['shed']['WHEAT'])]\n        if not inv.get('WHEAT',0):\n            return _v219_walk(pos,home) or ['PASS']\n        _C410_REPORT['partial_service']+=1\n    if needed:\n        path=_sl_path(pos,needed)\n        current=farm['tiles'][pos[1]][pos[0]]\n        if pos in targets and isinstance(current,dict) and current.get('fed_today') and current.get('cared_today') and current.get('fertilizer_available'):\n            travel=_sl_dist(pos,path[0])+sum(_sl_dist(a,b) for a,b in zip(path,path[1:]))\n            work=sum(not farm['tiles'][y][x]['fed_today'] for x,y in path)+sum(not farm['tiles'][y][x]['cared_today'] for x,y in path)\n            delivery=_sl_dist(path[-1],_v219_home(path[-1]))+1 if step//24==29 else 0\n            remaining=min((step//24+1)*24,719)-step\n            if 1+travel+work+delivery<=remaining:\n                _SL_REPORT['collect']+=1\n                return ['COLLECT_FERTILIZER']\n        target=path[0];t=farm['tiles'][target[1]][target[0]]\n        return _v219_walk(pos,target) or (['FEED'] if not t['fed_today'] else ['CARE'])\n    # Essential work is complete. Collect what can still reach the shed on\n    # the final day; on earlier days the normal midnight deposit is sufficient.\n    remaining=719-step if step//24==29 else 24-step%24\n    tasks=[]\n    for target in targets:\n        t=farm['tiles'][target[1]][target[0]]\n        if not t.get('fertilizer_available'):continue\n        dist=_sl_dist(pos,target)\n        ret=_sl_dist(target,_v219_home(target))+1 if step//24==29 else 0\n        if dist+1+ret<=remaining:tasks.append((dist,tuple(target)))\n    if tasks:\n        _,target=min(tasks)\n        command=_v219_walk(pos,target) or ['COLLECT_FERTILIZER']\n        _SL_REPORT['collect']+=command==['COLLECT_FERTILIZER']\n        return command\n    if inv.get('FERTILIZER',0):\n        return _v219_walk(pos,home) or ['PLACE','FERTILIZER',inv['FERTILIZER']]\n    return ['PASS']",_C410_NS)
    if _C410_WORKER: _C410_NS['_VT_WORKER']=_C410_NS['_c410_compact_worker']

def _c410_pickup(obs, action):
    step = int(obs['step'])
    if not 144 <= step < 696:
        return action
    own = int(obs['player']); farm = obs['farms'][own]; private = obs['private']
    positions = [farm['farmer'], *farm['hands']]
    commands = [list(action.get('farmer') or ['PASS']), *[list(c or ['PASS']) for c in action.get('hands', [])]]
    access = ((4,4), (5,4), (4,5), (5,5))
    pickups = [(i,c) for i,c in enumerate(commands[:len(positions)]) if c[:2] == ['PICKUP','WHEAT'] and tuple(positions[i]) in access]
    original = sum(max(0, int(c[2]) if len(c)>2 else 1) for _,c in pickups)
    spare = max(0, private['shed'].get('WHEAT',0)-original)
    if not spare:
        return action
    extra = 0
    for actor, c in pickups:
        qty = max(0, int(c[2]) if len(c)>2 else 1)
        need = _c410_feed_need(obs, actor, c)
        add = min(spare-extra, max(0,need-private['inventories'][actor].get('WHEAT',0)-qty))
        if add:
            commands[actor] = ['PICKUP','WHEAT',qty+add]; extra += add
    if not extra:
        return action
    orders = action.get('market',[])
    _C410_REPORT['pickup_units'] += extra
    return dict(action,farmer=commands[0],hands=commands[1:],market=orders)


def _c410_overflow(obs, action):
    step = int(obs['step'])
    if step % 24 != 23 or step >= 695:
        return action
    orders = [list(o) for o in action.get('market',[])]
    if not any(o[0]=='BUY_PRODUCT' for o in orders) or not _C410_NS['_r97_budget'](obs,orders):
        return action
    _, p = _C410_NS['_ov_fields'](obs,action)
    stock, _, sales = _C410_NS['_r97_market_stock'](p['shed'],orders)
    final, loss = _C410_NS['_r97_delivery'](stock,p,True)
    if not loss:
        return action
    own = int(obs['player']); native = _C410_NS['_IMPL'].chassis.players[own]
    tape = _C410_NS['_IMPL'].chassis.routes[2 if step+1>=648 else native['route']]
    need = {'WHEAT':0,'FERTILIZER':0}
    for t in range(step+1,min(len(tape),step+25)):
        frame=tape[t]
        for c in [frame.get('farmer') or ['PASS'],*(frame.get('hands') or [])]:
            if c and c[0]=='PICKUP' and c[1] in need:
                need[c[1]] += max(0,int(c[2]) if len(c)>2 else 1)
    state = _C410_NS['_V233_STATES'].get(own) or {}
    need['WHEAT'] += sum(len(targets) for targets in state.get('workers',{}).values())
    # Dynamic fertiliser tours can consume seven units beyond native tape.
    need['FERTILIZER'] += 7
    changed=0
    for i,o in enumerate(orders):
        if o[0]!='BUY_PRODUCT' or o[1] not in need:
            continue
        while orders[i][2]>0:
            trial=[list(x) for x in orders];trial[i][2]-=1
            st,_,sold=_C410_NS['_r97_market_stock'](p['shed'],trial)
            af,al=_C410_NS['_r97_delivery'](st,p,True)
            if sold!=sales or sum(al.values())>=sum(loss.values()):
                break
            if any(af.get(k,0)<min(final.get(k,0),v) for k,v in need.items()):
                break
            if any(af.get(k,0)<q for k,q in final.items() if k not in need):
                break
            orders=trial;loss=al;changed+=1
    if not changed:
        return action
    _C410_REPORT['overflow_buys_avoided']+=changed
    return dict(action,market=orders)


_C410_PRE_SETTLEMENT = _C405_PARENT

def _c410_pre_settlement(obs, configuration=None):
    action = _C410_PRE_SETTLEMENT(obs, configuration)
    if _C410_ENABLED:
        if _C410_PICKUP: action = _c410_pickup(obs, action)
        if _C410_OVERFLOW: action = _c410_overflow(obs, action)
        action = _C410_NS['_c410_supply'](obs,action)
    return action

if _C410_ENABLED:
    _C405_PARENT = _c410_pre_settlement

def agent(observation, configuration=None):
    if int(observation['step'])==0:
        _C410_REPORT.clear()
        _C410_REPORT.update(pickup_units=0,pickup_slot_blocked=0,pickup_budget_blocked=0,
                            overflow_buys_avoided=0,partial_pickup=0,partial_service=0)
    result = _C410_PARENT(observation, configuration)
    _C410_TELEMETRY.clear();_C410_TELEMETRY.update(getattr(_C410_PARENT,'telemetry',{}))
    _C410_TELEMETRY.update({'c410_'+k:v for k,v in _C410_REPORT.items()})
    return result

agent.telemetry = _C410_TELEMETRY
c410_submission_agent = agent

# c412: late-evening grain orders must be funded before the nightly reset.
# Reuse the opening cash-floor approach, but reserve next-day fertiliser and
# apply only to early-economy night grain orders that otherwise buy partially.
_C412_ENABLED = False
_C412_PARENT = agent
_C412_REPORT = {}
_C412_TELEMETRY = {}


def _c412_fund(obs, action):
    step = int(obs['step'])
    if step % 24 != 23 or not 144 <= step < 288:
        return action
    orders = [list(o) for o in action.get('market', [])]
    if len(orders) >= 10 or not any(o[:2] == ['BUY_PRODUCT','WHEAT'] for o in orders):
        return action
    own = int(obs['player']); farm = obs['farms'][own]
    _, private = _C410_NS['_ov_fields'](obs, action)
    prices = obs['market']['prices']; stock = dict(private['shed'])
    cash = float(farm['money']); gap = 0; hires = int(farm['hires_today'])
    for o in orders:
        if o[0] == 'HIRE':
            cash -= _C410_NS['_v219_fib'](hires); hires += 1
        elif o[0] == 'BUY_LAND':
            cash -= 4000
        elif len(o) > 2:
            item, qty = o[1], max(0, int(o[2]))
            if o[0] == 'SELL':
                take = min(qty, stock.get(item,0)); stock[item] = stock.get(item,0)-take
                cash += take * max(1, int(prices[item])-2)
            elif o[0] == 'BUY_PRODUCT':
                cash -= qty*(int(prices[item])+2)
                if item == 'WHEAT': gap = max(gap,-cash)
            elif o[0] == 'BUY_SEED':
                cash -= qty*{'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}[item]
            elif o[0] == 'BUY_ANIMAL':
                cash -= qty*{'GOOSE':300,'COW':400,'SHEEP':500}[item]
    if gap <= 0:
        return action
    quote = max(1,int(prices['FERTILIZER'])-2)
    units = int(-(-gap//quote))
    free = private['shed'].get('FERTILIZER',0)-sum(o[2] for o in orders if o[:2]==['SELL','FERTILIZER'])
    if units > free or quote < 3:
        _C412_REPORT['funding_unavailable'] += 1; return action
    native = _C410_NS['_IMPL'].chassis.players[own]
    tape = _C410_NS['_IMPL'].chassis.routes[native['route']]
    reserve=0
    for t in range(step+1,step+25):
        frame=tape[t]
        for c in [frame.get('farmer') or ['PASS'],*(frame.get('hands') or [])]:
            if c and c[:2]==['PICKUP','FERTILIZER']:
                reserve += max(0,int(c[2]) if len(c)>2 else 1)
    proposed=[['SELL','FERTILIZER',units]]+orders
    stock,_,_=_C410_NS['_r97_market_stock'](private['shed'],proposed)
    final,_=_C410_NS['_r97_delivery'](stock,private,True)
    if final.get('FERTILIZER',0)<reserve:
        _C412_REPORT['funding_reserved'] += 1; return action
    _C412_REPORT['funding_turns'] += 1; _C412_REPORT['funding_units'] += units
    return dict(action,market=proposed)


def agent(observation, configuration=None):
    if int(observation['step'])==0:
        _C412_REPORT.clear()
        _C412_REPORT.update(funding_turns=0,funding_units=0,funding_unavailable=0,funding_reserved=0)
    action = _C412_PARENT(observation,configuration)
    if _C412_ENABLED: action = _c412_fund(observation,action)
    _C412_TELEMETRY.clear();_C412_TELEMETRY.update(getattr(_C412_PARENT,'telemetry',{}))
    _C412_TELEMETRY.update({'c412_'+k:v for k,v in _C412_REPORT.items()})
    return action

agent.telemetry = _C412_TELEMETRY
c412_submission_agent = agent

# c413: commit funding BEFORE c396 public-state projections and settlement.
# All emitted field/market changes must be included in the tracker's transition.
_C413_ENABLED = True
_C413_PRE_SETTLEMENT = _C405_PARENT
def _c413_pre_settlement(observation, configuration=None):
    action = _C413_PRE_SETTLEMENT(observation, configuration)
    return _c412_fund(observation, action) if _C413_ENABLED else action
if _C413_ENABLED:
    _C405_PARENT = _c413_pre_settlement
c413_submission_agent = agent

# c414 diagnostic: veto a chosen response if a surviving public hypothesis
# could reverse the benefit merely by reordering its existing sale slots.
# This finite uncertainty set is not a guarantee against arbitrary policies.
_C414_ENABLED = True
_C414_RESPONSE_ORIGINAL = _c396_response
_C414_REPORT = dict(offers=0, accepted=0, rejected=0, stress_cases=0, budget_declined=0)


def _c414_accept(obs, original, chosen, predicted, configuration):
    own = int(obs['player'])
    _C414_REPORT['offers'] += 1
    tested = 0
    for key, pa in predicted.items():
        orders = pa.get('market') or []
        slots = [i for i, o in enumerate(orders) if o and o[0] == 'SELL']
        if len(slots) > 4:
            _C414_REPORT['budget_declined'] += 1
            return False
        sales = [orders[i] for i in slots]
        variants = [[]]
        for permutation in _c396_it.permutations(sales):
            queue = list(orders)
            for i, order in zip(slots, permutation):
                queue[i] = order
            if queue != orders and queue not in variants:
                variants.append(queue)
        actions = [None, None]
        actions[own] = original
        actions[1-own] = pa
        farms, privates = _c396_fields(obs, _C396_MODELS[key]['private'], actions)
        for queue in variants:
            tested += 1
            if tested > 96:
                _C414_REPORT['budget_declined'] += 1
                return False
            queues = [None, None]
            queues[own] = original.get('market') or []
            queues[1-own] = queue
            base = _c396_market(farms, privates, obs['market'], queues, configuration, own)
            queues[own] = chosen.get('market') or []
            new = _c396_market(farms, privates, obs['market'], queues, configuration, own)
            _C414_REPORT['stress_cases'] += 1
            if new[2:] != base[2:] or new[0] < base[0] or new[1] < base[1]:
                return False
    return True


def _c414_response(obs, action, predicted, configuration):
    before = (_C396_REPORT['c396_turns'], _C396_REPORT['c396_predicted_margin'])
    chosen = _C414_RESPONSE_ORIGINAL(obs, action, predicted, configuration)
    if chosen == action:
        return chosen
    if _c414_accept(obs, action, chosen, predicted, configuration):
        _C414_REPORT['accepted'] += 1
        return chosen
    _C414_REPORT['rejected'] += 1
    _C396_REPORT['c396_turns'], _C396_REPORT['c396_predicted_margin'] = before
    return action


if _C414_ENABLED:
    _c396_response = _c414_response
_C414_PARENT = agent
_C414_TELEMETRY = {}


def agent(observation, configuration=None):
    if int(observation['step']) == 0:
        for key in _C414_REPORT:
            _C414_REPORT[key] = 0
    result = _C414_PARENT(observation, configuration)
    _C414_TELEMETRY.clear()
    _C414_TELEMETRY.update(getattr(_C414_PARENT, 'telemetry', {}))
    _C414_TELEMETRY.update({'c414_'+k:v for k,v in _C414_REPORT.items()})
    return result


agent.telemetry = _C414_TELEMETRY
c414_submission_agent = agent

# c416: public shadow coverage expansion. Taeyang/Codex 2026-09-23.
# Adds reviewed public sources 267,284,306,308,312; all embedded original source notices are retained.
# Only the hypothesis set changes. Source IDs below are internal dictionary
# keys, never a runtime opponent identifier or an input from Kaggle.
