# c418: respond to observed tick wheat round trips. Taeyang/Codex.
# Only our state and past public inventories are inputs. No opponent ID/source,
# replay labels, private opponent inventory, seed, or future observations.
_C418_ENABLED = True
_C418_PARENT = _C396_PARENT
_C418_STATE = {}
_C418_REPORT = {}
_C418_SEED_COST = dict(WHEAT=10,CARROT=20,TOMATO=50,STRAWBERRY=100,MELON=80)


def _c418_update(obs):
    t=int(obs['step']);own=int(obs['player']);st=_C418_STATE
    prev=st.get('prev')
    if not prev or prev['step']!=t-1:
        return
    known=prev['no_wheat']
    pair=prev.get('pair')
    if pair:
        # Tick entries never cross end-of-day. All seed buys are fully funded;
        # field actions precede trading and have already been simulated exactly.
        known=obs['private']['shed']==pair['shed']
        if not known:
            st['disabled']=True;_C418_REPORT['conservation_failures']+=1
        profit=obs['farms'][own]['money']-prev['cash']+pair['seed_cost']
        _C418_REPORT['realized_profit']+=profit
        st['loss_streak']=st.get('loss_streak',0)+1 if profit < -5 else 0
        if st['loss_streak']>=2:
            st['disabled']=True;_C418_REPORT['stop_loss']+=1
    if not known:
        return
    past=t-1
    draw=0
    if past%4==0:
        draw=sum(1 for s in prev['shops'] if 'WHEAT' in _C396_ENGINE['SHOPS'][s])
    draw+=int(past%24==0)
    net=obs['market']['inventory']['WHEAT']-prev['inventory']+draw
    st['net'][past]=net
    for key in list(st['net']):
        if key < t-20:del st['net'][key]
    if past%4==1 and st['net'].get(past-1,0)<=-20 and net>=.8*(-st['net'][past-1]):
        st['trips'].append((past-1,-st['net'][past-1]))
        _C418_REPORT['observed_trips']+=1
    st['trips']=[p for p in st['trips'] if p[0]>=t-16]
    if past%4==0:
        st['misses']=0 if net<=-20 else st.get('misses',0)+1
        if st['misses']>=3:st['latched']=False
    if len(st['trips'])>=2:
        st['latched']=True


def _c418_offer(obs,action,configuration):
    t=int(obs['step']);own=int(obs['player']);st=_C418_STATE
    if st.get('disabled') or not st.get('latched') or not 144<=t<647 or t%4:
        return action,None
    cfg=dict(configuration or {})
    if any(cfg.get(k,v)!=v for k,v in [('boardSize',10),('turnsPerDay',24),('shedCapacity',100),('maxMarketOrdersPerTurn',10)]):
        return action,None
    orders=action.get('market') or []
    # Never shift any existing price-sensitive, land, animal, or hire order.
    # Seed-only ticks preserve all premium-sale slots by leaving them untouched.
    if len(orders)>8 or any(o and not (len(o)==3 and o[0]=='BUY_SEED' and o[1] in _C418_SEED_COST and type(o[2]) is int and 0<o[2]<=100) for o in orders):
        _C418_REPORT['order_declines']+=1;return action,None
    native=_C358_IMPL.chassis;route=native.players[own]['route']
    future=native.routes[route][t+1]
    for frame in (action,future):
        if any(c[:2]==['PICKUP','WHEAT'] for c in [frame.get('farmer') or ['PASS']]+list(frame.get('hands') or [])):
            _C418_REPORT['pickup_declines']+=1;return action,None
    actions=[{},{}];actions[own]=action
    farms,privates=_c396_fields(obs,_C396_ENGINE['_new_private'](),actions)
    shed=privates[own]['shed']
    seed_cost=sum(o[2]*_C418_SEED_COST[o[1]] for o in orders if o)
    # At the $1 floor sales do not restore public supply. Exclude that case
    # even under ten full opponent sales, so a verified pair has zero own net.
    if _C365_CA_NS['_r37_market_price']('WHEAT',obs['market']['inventory']['WHEAT']+1000)<=1:
        _C418_REPORT['funding_declines']+=1;return action,None
    upper=_C365_CA_NS['_r37_market_price']('WHEAT',obs['market']['inventory']['WHEAT']-2000)
    estimate=max(q for _,q in st['trips']) if st['trips'] else 0
    q=min(100,int(1.2*estimate),100-sum(shed.values())-5,int((farms[own]['money']-2500-seed_cost)//max(upper,1)))
    if q<10:
        _C418_REPORT['funding_declines']+=1;return action,None
    market=[['BUY_PRODUCT','WHEAT',q]]+[list(o) for o in orders]
    market+=[[] for _ in range(9-len(market))]
    market.append(['SELL','WHEAT',q])
    if not _C365_CA_NS['_r97_budget'](obs,market):
        _C418_REPORT['funding_declines']+=1;return action,None
    _C418_REPORT['pairs']+=1;_C418_REPORT['units']+=q
    result=dict(action);result['market']=market
    return result,dict(shed=_c396_copy.deepcopy(shed),seed_cost=seed_cost)


def _c418_parent(observation,configuration=None):
    t=int(observation['step']);own=int(observation['player'])
    if t==0:
        _C418_STATE.clear();_C418_STATE.update(net={},trips=[],latched=False,disabled=False)
        _C418_REPORT.clear();_C418_REPORT.update(observed_trips=0,pairs=0,units=0,realized_profit=0,stop_loss=0,conservation_failures=0,order_declines=0,pickup_declines=0,funding_declines=0)
    _c418_update(observation)
    action=_C418_PARENT(observation,configuration)
    action,pair=_c418_offer(observation,action,configuration)
    orders=action.get('market') or []
    _C418_STATE['prev']=dict(step=t,cash=observation['farms'][own]['money'],inventory=observation['market']['inventory']['WHEAT'],shops=list(observation['town']['unlocked_shops']),pair=pair,
        no_wheat=not any(o and len(o)>=2 and o[1]=='WHEAT' and o[0] in ('BUY_PRODUCT','SELL') for o in orders))
    return action


if _C418_ENABLED:
    _C396_PARENT=_c418_parent
_C418_ENTRY=agent
_C418_TELEMETRY={}


def agent(observation,configuration=None):
    result=_C418_ENTRY(observation,configuration)
    _C418_TELEMETRY.clear();_C418_TELEMETRY.update(getattr(_C418_ENTRY,'telemetry',{}))
    _C418_TELEMETRY.update({'c418_'+k:v for k,v in _C418_REPORT.items()})
    return result


agent.telemetry=_C418_TELEMETRY
c418_submission_agent=agent

# c419: preserve the two-leg slot contract through the inherited response layer.
# c396 can move a single SELL across BUY_SEED; c418's assumption was too weak.
_C419_ENABLED = True
_C419_RESPONSE = _c396_response
_C419_BLOCKED = 0

def _c419_response(obs, action, predicted, configuration):
    global _C419_BLOCKED
    prev = _C418_STATE.get('prev') or {}
    if prev.get('step') == int(obs['step']) and prev.get('pair') is not None:
        _C419_BLOCKED += 1
        return action
    return _C419_RESPONSE(obs, action, predicted, configuration)

if _C419_ENABLED:
    _c396_response = _c419_response
_C419_ENTRY = agent
_C419_TELEMETRY = {}

def agent(observation, configuration=None):
    global _C419_BLOCKED
    if int(observation['step']) == 0:
        _C419_BLOCKED = 0
    result = _C419_ENTRY(observation, configuration)
    _C419_TELEMETRY.clear()
    _C419_TELEMETRY.update(getattr(_C419_ENTRY, 'telemetry', {}))
    _C419_TELEMETRY['c419_pinned_responses'] = _C419_BLOCKED
    return result

agent.telemetry = _C419_TELEMETRY
c419_submission_agent = agent

