# c461: exact F_11 queue-search algorithm, kept behind c419/c414 protections.
import json as _c461_json
_C461_ENABLED = True
_C461_DONOR = '"""State-constrained two-pass queue search. No observed opponent IDs or future data.\nCandidates may split an existing lot and execute inventory-neutral round trips.\nEvery candidate is evaluated by the unmodified per-unit market interpreter.\n"""\n_F11_PARENT_RESPONSE=_c396_response\n_F11_REPORT={}\n\ndef _f11_neighbours(orders,shed,rivals):\n    slots=[list(o) for o in orders]+[[] for _ in range(10-len(orders))]\n    moving=[i for i,o in enumerate(slots) if len(o)==3 and o[0] in (\'SELL\',\'BUY_PRODUCT\') and int(o[2])>0]\n    holes=[i for i,o in enumerate(slots) if not o]\n    # Main missing operation: preserve the total lot but divide its execution.\n    for i in moving:\n        op,item,q=slots[i];q=int(q)\n        if q<2:continue\n        for j in holes:\n            for part in dict.fromkeys((q//2,1,q-1)):\n                if not 0<part<q:continue\n                x=[o[:] for o in slots];x[i]=[op,item,q-part];x[j]=[op,item,part];yield x\n    # Existing trades may move without touching fixed-price investments.\n    for i in moving:\n        for j in holes+moving:\n            if j==i:continue\n            x=[o[:] for o in slots];x[i],x[j]=x[j],x[i];yield x\n    if len(holes)<2:return\n    opportunities=set()\n    for rival in rivals:\n        for pivot,o in enumerate(rival[:10]):\n            if len(o)==3 and o[0] in (\'BUY_PRODUCT\',\'SELL\') and o[1] in (\'WHEAT\',\'FERTILIZER\') and int(o[2])>0:\n                opportunities.add((pivot,o[1],o[0],int(o[2])))\n    for pivot,item,kind,rival_qty in sorted(opportunities):\n        lefts=[j for j in holes if j<=pivot];rights=[j for j in holes if j>=pivot]\n        if not lefts or not rights:continue\n        pairs=sorted({(max(lefts),min(rights)),(min(lefts),max(rights)),(min(lefts),min(rights))})\n        for left,right in pairs:\n            if left>=right:continue\n            ops=(\'SELL\',\'BUY_PRODUCT\') if kind==\'SELL\' else (\'BUY_PRODUCT\',\'SELL\')\n            maxq=min(96,int(shed.get(item,0))) if ops[0]==\'SELL\' else max(0,100-sum(shed.values()))\n            for q in dict.fromkeys((min(maxq,rival_qty),min(maxq,64),min(maxq,32),min(maxq,16),min(maxq,8),1)):\n                if q<1 or q>maxq:continue\n                x=[o[:] for o in slots];x[left]=[ops[0],item,q];x[right]=[ops[1],item,q];yield x\n\ndef _f11_response(obs,action,predicted,configuration):\n    step=int(obs[\'step\']);own=int(obs[\'player\']);orders=action.get(\'market\') or []\n    if not _F11_REPORT:_F11_REPORT.update(beam_calls=0,beam_scored=0,beam_changes=0,beam_gain=0)\n    inherited=_F11_PARENT_RESPONSE(obs,action,predicted,configuration)\n    if not predicted or len(orders)>10:return inherited\n    contexts=[];seen=set();rivals=[]\n    for key,op in predicted.items():\n        private=_C396_MODELS[key][\'private\'];identity=_f9_json.dumps((private,op),sort_keys=True,separators=(\',\',\':\'))\n        if identity in seen:continue\n        seen.add(identity);acts=[None,None];acts[own]=action;acts[1-own]=op\n        farms,ps=_c396_fields(obs,private,acts);qs=[None,None];qs[own]=orders;qs[1-own]=op.get(\'market\') or []\n        base=_c396_market(farms,ps,obs[\'market\'],qs,configuration,own)\n        contexts.append((farms,ps,qs,base));rivals.append(qs[1-own])\n    def score(candidate):\n        ds=[];own_ds=[]\n        for fs,ps,qs,base in contexts:\n            q=qs[:];q[own]=candidate\n            out=_c396_market(fs,ps,obs[\'market\'],q,configuration,own)\n            if out[2:]!=base[2:] or out[0]<base[0] or out[1]<base[1]:return None\n            ds.append(out[1]-base[1]);own_ds.append(out[0]-base[0])\n        return min(ds),sum(ds),sum(own_ds)\n    chosen=[list(o) for o in inherited.get(\'market\',[])];best=score(chosen)\n    if best is None:return inherited\n    baseline_quality=best;beam=[chosen];visited={tuple(tuple(o) for o in chosen)};scored=0\n    # Bounded operation count rather than machine-speed-dependent behavior.\n    for depth in range(2):\n        survivors=[]\n        for parent in beam:\n            for q in _f11_neighbours(parent,contexts[0][1][own][\'shed\'],rivals):\n                while q and not q[-1]:q.pop()\n                ident=tuple(tuple(o) for o in q)\n                if ident in visited:continue\n                visited.add(ident);scored+=1\n                quality=score(q)\n                if quality is not None and quality>baseline_quality:\n                    survivors.append((quality,q))\n                    if quality>best:best=quality;chosen=q\n                if scored>=192:break\n            if scored>=192:break\n        if not survivors or scored>=192:break\n        survivors.sort(key=lambda x:x[0],reverse=True);beam=[q for _,q in survivors[:2]]\n    _F11_REPORT[\'beam_calls\']+=1;_F11_REPORT[\'beam_scored\']+=scored\n    if best>baseline_quality:\n        _F11_REPORT[\'beam_changes\']+=1;_F11_REPORT[\'beam_gain\']+=best[0]-baseline_quality[0]\n        return dict(action,market=chosen)\n    return inherited\n\n_c396_response=_f11_response\n'
_C461_REPORT = dict(offers=0)
"""Whole frozen F_11 two-pass queue search behind current c419 protections.

This is the unchanged donor search, not a tuned c459 split. Its extra search
operations include inventory-neutral two-leg trades and moving variable-price
purchases. The parent's protected output is the baseline for every proposal.
"""
def _c461_choose(g, obs, action, predicted, cfg):
    step=int(obs['step']);pin=g['_C418_STATE'].get('prev') or {}
    if not 216<=step<=706 or not predicted:return action
    if pin.get('step')==step and pin.get('pair') is not None:return action
    ns=g.get('_C461_SEARCH')
    if ns is None:
        def unchanged(obs, action, predicted, configuration):return action
        ns=dict(_c396_response=unchanged,_c396_fields=g['_c396_fields'],_c396_market=g['_c396_market'],
                _C396_MODELS=g['_C396_MODELS'],_f9_json=_c461_json)
        # Static-extracted source is frozen by the diagnostic manifest.
        exec(compile(_C461_DONOR,'F11-original-search','exec'),ns)
        g['_C461_SEARCH']=ns
    ns['_C396_MODELS']=g['_C396_MODELS']
    proposal=ns['_f11_response'](obs,action,predicted,cfg)
    if proposal==action:return action
    saved=dict(g['_C414_REPORT'])
    try:
        return proposal if g['_c414_accept'](obs,action,proposal,predicted,cfg) else action
    finally:
        g['_C414_REPORT'].clear();g['_C414_REPORT'].update(saved)

_C461_RESPONSE = _c396_response
def _c461_response(obs, action, predicted, configuration):
    baseline = _C461_RESPONSE(obs, action, predicted, configuration)
    selected = _c461_choose(globals(), obs, baseline, predicted, configuration)
    if selected != baseline: _C461_REPORT['offers'] += 1
    return selected
if _C461_ENABLED: _c396_response = _c461_response
_C461_ENTRY = agent
_C461_TELEMETRY = {}
def agent(observation, configuration=None):
    if int(observation['step']) == 0:
        globals().pop('_C461_SEARCH', None)
        _C461_REPORT['offers'] = 0
    result = _C461_ENTRY(observation, configuration)
    _C461_TELEMETRY.clear()
    _C461_TELEMETRY.update(getattr(_C461_ENTRY, 'telemetry', {}))
    _C461_TELEMETRY.update({'c461_'+k:v for k,v in _C461_REPORT.items()})
    _C461_TELEMETRY.update({'c461_'+k:v for k,v in globals().get('_C461_SEARCH',{}).get('_F11_REPORT',{}).items()})
    return result
agent.telemetry = _C461_TELEMETRY
c461_submission_agent = agent



