exec(compile('# v4: complete-plan idle native actors deposit all cargo and finish at the shed.\n"""Observation-only terminal native recovery; partial plans retain closed trips.\n\nUses our already constructed physical plan, never a recorded future action,\nopponent identifier, seed, inferred private state or future shop draw.\n"""\nimport copy\n\nACCESS = ((4, 4), (5, 4), (4, 5), (5, 5))\nPRODUCT = {\'GOOSE\': \'EGG\', \'COW\': \'MILK\', \'SHEEP\': \'WOOL\'}\n\n\ndef walk(start, end):\n    x, y = start\n    tx, ty = end\n    return ([[\'EAST\' if tx > x else \'WEST\'] for _ in range(abs(tx-x))]\n            + [[\'SOUTH\' if ty > y else \'NORTH\'] for _ in range(abs(ty-y))])\n\n\nclass FullPlanRecovery:\n    def __init__(self, scope):\n        self.scope = scope\n        self.jobs = {}\n        self.stats = {\'jobs\': 0, \'changed_units\': 0, \'sale_orders\': 0,\n                      \'declined\': 0, \'aborted\': 0}\n\n    def reset(self):\n        self.jobs.clear()\n        for key in self.stats:\n            self.stats[key] = 0\n\n    def transform(self, obs, action, configuration=None):\n        step, seat = int(obs[\'step\']), int(obs[\'player\'])\n        if step == 0:\n            self.reset()\n        cfg = configuration or {}\n        if not 707 <= step <= 718 or any(cfg.get(k, v) != v for k, v in (\n                (\'episodeSteps\', 720), (\'boardSize\', 10), (\'turnsPerDay\', 24),\n                (\'shedCapacity\', 100), (\'maxMarketOrdersPerTurn\', 10))):\n            return action\n        plan = self.scope.get(\'_C379_STATE\', {}).get(seat)\n        if not isinstance(plan, dict):\n            self.stats[\'declined\'] += 1\n            return action\n        farm, private = obs[\'farms\'][seat], obs[\'private\']\n        positions = [tuple(farm[\'farmer\']), *map(tuple, farm[\'hands\'])]\n        if any(i not in plan for i in range(len(positions))):\n            # Future work by controllers outside the compacted native plan is\n            # unknown. Do not take a tile they could subsequently service.\n            self.stats[\'declined\'] += 1\n            return action\n        units = [action.get(\'farmer\') or [\'PASS\'], *(action.get(\'hands\') or [])]\n        units += [[\'PASS\'] for _ in range(len(positions)-len(units))]\n        # Only native actors proven idle for the complete remaining horizon.\n        idle = {i for i in plan if i < len(positions) and units[i] == [\'PASS\']\n                and all(cmd == [\'PASS\'] for t, cmd in plan[i].items() if t >= step)}\n        jobs = self.jobs.setdefault(seat, {})\n        for i in list(jobs):\n            if i not in idle or positions[i] != jobs[i][\'expected\']:\n                del jobs[i]\n                self.stats[\'aborted\'] += 1\n        # Mark every location with future planned productive work as reserved.\n        # Movement itself cannot block another worker in this game.\n        reserved = set()\n        for i, route in plan.items():\n            if i >= len(positions):\n                continue\n            x, y = positions[i]\n            for t in range(step, 719):\n                cmd = route.get(t, [\'PASS\'])\n                op = cmd[0]\n                if op in (\'HARVEST\', \'WATER\', \'COLLECT_FERTILIZER\', \'CARE\', \'FEED\',\n                          \'FERTILIZE\', \'DIG\', \'PLANT\', \'BUILD_COOP\', \'BUILD_PASTURE\'):\n                    reserved.add((x, y))\n                if op == \'EAST\': x += 1\n                if op == \'WEST\': x -= 1\n                if op == \'SOUTH\': y += 1\n                if op == \'NORTH\': y -= 1\n        busy = {j[\'target\'] for j in jobs.values()}\n        options = []\n        for y, row in enumerate(farm[\'tiles\']):\n            for x, tile in enumerate(row):\n                target = (x, y)\n                if (target in reserved or target in busy or not isinstance(tile, dict)\n                        or tile.get(\'animal\') not in PRODUCT):\n                    continue\n                resources = []\n                if tile.get(\'yield_units\', 0) > 0:\n                    resources.append((PRODUCT[tile[\'animal\']], int(tile[\'yield_units\']), [\'HARVEST\']))\n                if tile.get(\'fertilizer_available\'):\n                    resources.append((\'FERTILIZER\', 1, [\'COLLECT_FERTILIZER\']))\n                for item, quantity, service in resources:\n                    for i in sorted(idle-set(jobs)):\n                        if any(private[\'inventories\'][i].values()):\n                            continue\n                        origin = positions[i]\n                        home = min(ACCESS, key=lambda h: (len(walk(target, h)), h))\n                        seq = (walk(origin,target)+[service]+walk(target,home)\n                               +[[\'PLACE\',item,quantity]])\n                        # Complete by 717, leaving a spare turn for sale/deposit.\n                        if step+len(seq)-1 > 717:\n                            continue\n                        value = quantity * int(obs[\'market\'][\'prices\'].get(item, 1))\n                        options.append((-value/len(seq), len(seq), i, target, item, quantity, seq))\n        for _, _, i, target, item, qty, seq in sorted(options):\n            # Two simultaneous trips bound appended market orders to two.\n            if len(jobs) >= 2:\n                break\n            if i in jobs or target in busy:\n                continue\n            jobs[i] = {\'target\': target, \'item\': item, \'quantity\': qty,\n                       \'seq\': seq, \'index\': 0, \'expected\': positions[i]}\n            busy.add(target)\n            self.stats[\'jobs\'] += 1\n        if not jobs:\n            return action\n        orders = copy.deepcopy(action.get(\'market\') or [])\n        if len(orders) > 8 or any(o[0] != \'SELL\' for o in orders):\n            self.stats[\'declined\'] += 1\n            return action\n        # Exact embedded official primitive, with only our visible farm/private.\n        ns = self.scope[\'_C365_CA_NS\'][\'_PLANNER_NS\']\n        bf, bp = ns[\'_clone_state\'](farm, private)\n        peak_shed = sum(bp[\'shed\'].values())\n        for i, cmd in enumerate(units):\n            ns[\'_apply_unit_action\'](bf, bp, i, cmd, 10, 29, 24, 100)\n            peak_shed = max(peak_shed, sum(bp[\'shed\'].values()))\n        f, p = ns[\'_clone_state\'](farm, private)\n        delivered = {}\n        executed = []\n        for i, original in enumerate(units):\n            cmd = original\n            job = jobs.get(i)\n            if job:\n                proposed = job[\'seq\'][job[\'index\']]\n                if proposed[0] == \'PLACE\':\n                    # Empty starting cargo + one exclusive harvest job owns all\n                    # carried units, including visible yield accrued en route.\n                    qty = int(p[\'inventories\'][i].get(job[\'item\'], 0))\n                    if qty and peak_shed+sum(delivered.values())+qty <= 100:\n                        cmd = [\'PLACE\', job[\'item\'], qty]\n                        delivered[job[\'item\']] = delivered.get(job[\'item\'], 0)+qty\n                    # Otherwise keep the trip pending; never discard cargo.\n                else:\n                    cmd = proposed\n                if cmd != original:\n                    executed.append(i)\n                    units[i] = cmd\n            ns[\'_apply_unit_action\'](f, p, i, cmd, 10, 29, 24, 100)\n        for item, qty in sorted(delivered.items()):\n            # Original orders may already sell some/all of the delivered item.\n            existing = sum(int(o[2]) for o in orders if o[:2] == [\'SELL\', item])\n            available = max(0, int(p[\'shed\'].get(item, 0))-existing)\n            extra = min(qty, available)\n            if extra:\n                orders.append([\'SELL\', item, extra])\n                self.stats[\'sale_orders\'] += 1\n        for i in executed:\n            job = jobs[i]\n            job[\'index\'] += 1\n            job[\'expected\'] = tuple(([f[\'farmer\']]+f[\'hands\'])[i])\n            if job[\'index\'] == len(job[\'seq\']):\n                del jobs[i]\n        self.stats[\'changed_units\'] += len(executed)\n        return dict(action, farmer=units[0], hands=units[1:], market=orders)\n\n\n\n"""Observation-only terminal native recovery; partial plans retain closed trips.\n\nUses our already constructed physical plan, never a recorded future action,\nopponent identifier, seed, inferred private state or future shop draw.\n"""\nimport copy\n\nACCESS = ((4, 4), (5, 4), (4, 5), (5, 5))\nPRODUCT = {\'GOOSE\': \'EGG\', \'COW\': \'MILK\', \'SHEEP\': \'WOOL\'}\n\n\ndef walk(start, end):\n    x, y = start\n    tx, ty = end\n    return ([[\'EAST\' if tx > x else \'WEST\'] for _ in range(abs(tx-x))]\n            + [[\'SOUTH\' if ty > y else \'NORTH\'] for _ in range(abs(ty-y))])\n\n\nclass TerminalRecovery(FullPlanRecovery):\n    def __init__(self, scope):\n        self.scope = scope\n        self.jobs = {}\n        self.stats = {\'jobs\': 0, \'changed_units\': 0, \'sale_orders\': 0,\n                      \'declined\': 0, \'aborted\': 0, \'extra_idle\': 0,\n                      \'unknown_actors\': 0, \'reserved_dynamic\': 0,\n                      \'full_plan_turns\': 0, \'extended_turns\': 0}\n\n    def reset(self):\n        self.jobs.clear()\n        for key in self.stats:\n            self.stats[key] = 0\n\n    def continuations(self, obs, plan):\n        """Own compact plan plus frozen native tails; no recorded future actions.\n\n        Extra reactive crews reserve all their declared targets. Only an\n        unassigned native PASS tail or a sheep crew with no remaining work\n        may become idle. Sheep crews recover MILK/EGG only: their own cargo\n        return logic recognizes WOOL/FERTILIZER and would interrupt a trip.\n        """\n        step, seat = int(obs[\'step\']), int(obs[\'player\'])\n        farm, private = obs[\'farms\'][seat], obs[\'private\']\n        count = len(farm[\'hands\']) + 1\n        routes = {i: route for i, route in plan.items() if i < count}\n        allowed = {i: set(PRODUCT.values()) | {\'FERTILIZER\'} for i in routes}\n        ns = self.scope.get(\'_C365_CA_NS\', {})\n        impl = self.scope.get(\'_C358_IMPL\') or ns.get(\'_IMPL\')\n        chassis = getattr(impl, \'chassis\', None)\n        tape = getattr(chassis, \'routes\', {}).get(2) if chassis else None\n        reserved, owners = set(), {}\n\n        def targets(role):\n            if isinstance(role, (list, tuple)):\n                result = []\n                for target in role:\n                    if isinstance(target, (list, tuple)) and len(target) >= 2 and all(type(x) is int for x in target[:2]):\n                        result.append(tuple(target[:2]))\n                return result\n            if isinstance(role, dict):\n                return targets(role.get(\'targets\', role.get(\'path\', [])))\n            return []\n\n        for key in (\'_V219_STATES\', \'_V233_STATES\', \'_R51_INPUT_STATES\'):\n            state = ns.get(key, {}).get(seat, {})\n            for actor, role in state.get(\'workers\', {}).items():\n                owners[actor] = (key, role)\n                reserved.update(targets(role))\n        # Placement controllers are not idle merely because a raw slot is PASS.\n        cow_state = ns.get(\'_V231_STATES\', {}).get(seat, {})\n        carrying = {i for i, qty in cow_state.get(\'carrying\', {}).items() if qty}\n        reserved.update(tuple(x) for x in cow_state.get(\'sites\', {}))\n        self.stats[\'reserved_dynamic\'] = len(reserved)\n        for actor in range(count):\n            if actor in routes:\n                continue\n            if tape is None or len(tape) < 719:\n                self.stats[\'unknown_actors\'] += 1\n                # An opaque controller may service any animal. Preserve its\n                # possible work, without rejecting every known native actor.\n                reserved.update((x, y) for y, row in enumerate(farm[\'tiles\'])\n                                for x, tile in enumerate(row)\n                                if isinstance(tile, dict) and tile.get(\'animal\'))\n                continue\n            tail = {}\n            for t in range(step, 719):\n                frame = tape[t]\n                commands = [frame.get(\'farmer\') or [\'PASS\'], *(frame.get(\'hands\') or [])]\n                tail[t] = commands[actor] if actor < len(commands) else [\'PASS\']\n            # Retain non-idle native tails as reservations too.\n            routes[actor] = tail\n            if actor in carrying:\n                allowed[actor] = set()\n                continue\n            owner = owners.get(actor)\n            if owner is None:\n                allowed[actor] = set(PRODUCT.values()) | {\'FERTILIZER\'}\n            elif owner[0] == \'_V233_STATES\':\n                sites = targets(owner[1])\n                tiles = [farm[\'tiles\'][y][x] for x, y in sites]\n                done = bool(sites) and all(isinstance(tile, dict)\n                    and tile.get(\'animal\') == \'SHEEP\' and not tile.get(\'yield_units\', 0)\n                    and not tile.get(\'fertilizer_available\') and tile.get(\'fed_today\')\n                    and tile.get(\'cared_today\') for tile in tiles)\n                allowed[actor] = {\'MILK\', \'EGG\'} if done else set()\n            else:\n                allowed[actor] = set()\n            if allowed[actor] and all(cmd == [\'PASS\'] for cmd in tail.values()):\n                self.stats[\'extra_idle\'] += 1\n        return routes, reserved, allowed\n\n    def transform(self, obs, action, configuration=None):\n        seat = int(obs[\'player\'])\n        plan = self.scope.get(\'_C379_STATE\', {}).get(seat)\n        count = 1 + len(obs[\'farms\'][seat][\'hands\'])\n        if isinstance(plan, dict) and all(actor in plan for actor in range(count)):\n            # c379 overrides every compact-plan actor\'s actual field command.\n            # Only complete compact plans own every remaining field command.\n            # Their idle native actors may finish at the shed after depositing\n            # all recovery cargo; partial plans retain the frozen v3 trips.\n            if 707 <= int(obs[\'step\']) <= 718:\n                self.stats[\'full_plan_turns\'] += 1\n            return FullPlanRecovery.transform(self, obs, action, configuration)\n        if 707 <= int(obs[\'step\']) <= 718:\n            self.stats[\'extended_turns\'] += 1\n        step, seat = int(obs[\'step\']), int(obs[\'player\'])\n        if step == 0:\n            self.reset()\n        cfg = configuration or {}\n        if not 707 <= step <= 718 or any(cfg.get(k, v) != v for k, v in (\n                (\'episodeSteps\', 720), (\'boardSize\', 10), (\'turnsPerDay\', 24),\n                (\'shedCapacity\', 100), (\'maxMarketOrdersPerTurn\', 10))):\n            return action\n        plan = self.scope.get(\'_C379_STATE\', {}).get(seat)\n        if not isinstance(plan, dict):\n            self.stats[\'declined\'] += 1\n            return action\n        farm, private = obs[\'farms\'][seat], obs[\'private\']\n        positions = [tuple(farm[\'farmer\']), *map(tuple, farm[\'hands\'])]\n        routes, dynamic_reserved, allowed = self.continuations(obs, plan)\n        units = [action.get(\'farmer\') or [\'PASS\'], *(action.get(\'hands\') or [])]\n        units += [[\'PASS\'] for _ in range(len(positions)-len(units))]\n        # Only native actors proven idle for the complete remaining horizon.\n        idle = {i for i in routes if i < len(positions) and units[i] == [\'PASS\']\n                and all(cmd == [\'PASS\'] for t, cmd in routes[i].items() if t >= step)}\n        jobs = self.jobs.setdefault(seat, {})\n        for i in list(jobs):\n            if i not in idle or positions[i] != jobs[i][\'expected\']:\n                del jobs[i]\n                self.stats[\'aborted\'] += 1\n        # Mark every location with future planned productive work as reserved.\n        # Movement itself cannot block another worker in this game.\n        reserved = set(dynamic_reserved)\n        for i, route in routes.items():\n            if i >= len(positions):\n                continue\n            x, y = positions[i]\n            for t in range(step, 719):\n                cmd = route.get(t, [\'PASS\'])\n                op = cmd[0]\n                if op in (\'HARVEST\', \'WATER\', \'COLLECT_FERTILIZER\', \'CARE\', \'FEED\',\n                          \'FERTILIZE\', \'DIG\', \'PLANT\', \'BUILD_COOP\', \'BUILD_PASTURE\'):\n                    reserved.add((x, y))\n                if op == \'EAST\': x += 1\n                if op == \'WEST\': x -= 1\n                if op == \'SOUTH\': y += 1\n                if op == \'NORTH\': y -= 1\n        busy = {j[\'target\'] for j in jobs.values()}\n        options = []\n        for y, row in enumerate(farm[\'tiles\']):\n            for x, tile in enumerate(row):\n                target = (x, y)\n                if (target in reserved or target in busy or not isinstance(tile, dict)\n                        or tile.get(\'animal\') not in PRODUCT):\n                    continue\n                resources = []\n                if tile.get(\'yield_units\', 0) > 0:\n                    resources.append((PRODUCT[tile[\'animal\']], int(tile[\'yield_units\']), [\'HARVEST\']))\n                if tile.get(\'fertilizer_available\'):\n                    resources.append((\'FERTILIZER\', 1, [\'COLLECT_FERTILIZER\']))\n                for item, quantity, service in resources:\n                    for i in sorted(idle-set(jobs)):\n                        if item not in allowed.get(i, set(PRODUCT.values()) | {\'FERTILIZER\'}):\n                            continue\n                        if any(private[\'inventories\'][i].values()):\n                            continue\n                        origin = positions[i]\n                        home = min(ACCESS, key=lambda h: (len(walk(target,h))+len(walk(h,origin)), h))\n                        seq = (walk(origin,target)+[service]+walk(target,home)\n                               +[[\'PLACE\',item,quantity]]+walk(home,origin))\n                        # Complete by 717, leaving a spare turn for sale/deposit.\n                        if step+len(seq)-1 > 717:\n                            continue\n                        value = quantity * int(obs[\'market\'][\'prices\'].get(item, 1))\n                        options.append((-value/len(seq), len(seq), i, target, item, quantity, seq))\n        for _, _, i, target, item, qty, seq in sorted(options):\n            # Two simultaneous trips bound appended market orders to two.\n            if len(jobs) >= 2:\n                break\n            if i in jobs or target in busy:\n                continue\n            jobs[i] = {\'target\': target, \'item\': item, \'quantity\': qty,\n                       \'seq\': seq, \'index\': 0, \'expected\': positions[i]}\n            busy.add(target)\n            self.stats[\'jobs\'] += 1\n        if not jobs:\n            return action\n        orders = copy.deepcopy(action.get(\'market\') or [])\n        if len(orders) > 8 or any(o[0] != \'SELL\' for o in orders):\n            self.stats[\'declined\'] += 1\n            return action\n        # Exact embedded official primitive, with only our visible farm/private.\n        ns = self.scope[\'_C365_CA_NS\'][\'_PLANNER_NS\']\n        bf, bp = ns[\'_clone_state\'](farm, private)\n        peak_shed = sum(bp[\'shed\'].values())\n        for i, cmd in enumerate(units):\n            ns[\'_apply_unit_action\'](bf, bp, i, cmd, 10, 29, 24, 100)\n            peak_shed = max(peak_shed, sum(bp[\'shed\'].values()))\n        f, p = ns[\'_clone_state\'](farm, private)\n        delivered = {}\n        executed = []\n        for i, original in enumerate(units):\n            cmd = original\n            job = jobs.get(i)\n            if job:\n                proposed = job[\'seq\'][job[\'index\']]\n                if proposed[0] == \'PLACE\':\n                    # The job starts empty and owns its sole HARVEST/COLLECT.\n                    # Sell actual cargo, including yield accrued en route.\n                    qty = max(0, int(p[\'inventories\'][i].get(job[\'item\'], 0)))\n                    if qty and peak_shed+sum(delivered.values())+qty <= 100:\n                        cmd = [\'PLACE\', job[\'item\'], qty]\n                        delivered[job[\'item\']] = delivered.get(job[\'item\'], 0)+qty\n                    # Otherwise keep the trip pending; never discard cargo.\n                else:\n                    cmd = proposed\n                if cmd != original:\n                    executed.append(i)\n                    units[i] = cmd\n            ns[\'_apply_unit_action\'](f, p, i, cmd, 10, 29, 24, 100)\n        for item, qty in sorted(delivered.items()):\n            # Original orders may already sell some/all of the delivered item.\n            existing = sum(int(o[2]) for o in orders if o[:2] == [\'SELL\', item])\n            available = max(0, int(p[\'shed\'].get(item, 0))-existing)\n            extra = min(qty, available)\n            if extra:\n                orders.append([\'SELL\', item, extra])\n                self.stats[\'sale_orders\'] += 1\n        for i in executed:\n            job = jobs[i]\n            job[\'index\'] += 1\n            job[\'expected\'] = tuple(([f[\'farmer\']]+f[\'hands\'])[i])\n            if job[\'index\'] == len(job[\'seq\']):\n                del jobs[i]\n        self.stats[\'changed_units\'] += len(executed)\n        return dict(action, farmer=units[0], hands=units[1:], market=orders)\n\n\ndef install(scope):\n    policy = TerminalRecovery(scope)\n    # c396 must project the emitted changes, rather than reject its hypotheses\n    # on the next observation merely because this layer was installed too late.\n    parent = scope[\'_C396_PARENT\']\n    def before_settlement(observation, configuration=None):\n        return policy.transform(observation, parent(observation, configuration), configuration)\n    scope[\'_C396_PARENT\'] = before_settlement\n    scope[\'_TERMINAL_RECOVERY\'] = policy\n    return policy\n', '<xox787-terminal-recovery-v4>', 'exec'), _C447_NS)
_C447_POLICY = _C447_NS['install'](globals()) if _C447_ENABLED else None

# c462: cumulative validated mechanisms; exact policies, unified telemetry.
_C462_ENTRY = agent
_C462_TELEMETRY = {}
def agent(observation, configuration=None):
    result = _C462_ENTRY(observation, configuration)
    _C462_TELEMETRY.clear()
    _C462_TELEMETRY.update(getattr(_C462_ENTRY, 'telemetry', {}))
    if _C447_POLICY is not None:
        _C462_TELEMETRY.update({'c447_'+k: v for k,v in _C447_POLICY.stats.items()})
    return result
agent.telemetry = _C462_TELEMETRY
c462_submission_agent = agent
# c465: residual empty-slot movement then one original guarded F11 pass.
_C465_ENABLED = True
_C465_REPORT = dict(offers=0)
def _c465_empty_choose(g, obs, action, predicted, cfg):
    step, own = int(obs['step']), int(obs['player'])
    orders = action.get('market') or []
    pin = g['_C418_STATE'].get('prev') or {}
    if not 216 <= step <= 706 or not predicted or len(orders) > 10:
        return action
    if pin.get('step') == step and pin.get('pair') is not None:
        return action
    queue = [list(o) for o in orders] + [[] for _ in range(10-len(orders))]
    slots = [i for i, o in enumerate(queue) if len(o) == 3 and o[0] == 'SELL' and type(o[2]) is int and o[2] > 0]
    holes = [i for i, o in enumerate(queue) if not o]
    if not 1 <= len(slots) <= 4 or not holes:
        return action
    contexts = []
    for key, pa in predicted.items():
        actions = [None, None]
        actions[own], actions[1-own] = action, pa
        farms, privates = g['_c396_fields'](obs, g['_C396_MODELS'][key]['private'], actions)
        queues = [a.get('market') or [] for a in actions]
        base = g['_c396_market'](farms, privates, obs['market'], queues, cfg, own)
        contexts.append((farms, privates, queues, base))
    best, selected = (0, 0), action
    saved_report = dict(g['_C414_REPORT'])
    try:
        for src in slots:
            for dest in holes:
                candidate = [list(o) for o in queue]
                candidate[src], candidate[dest] = candidate[dest], candidate[src]
                while candidate and not candidate[-1]:
                    candidate.pop()
                deltas = []
                for farms, privates, queues, base in contexts:
                    q = list(queues)
                    q[own] = candidate
                    result = g['_c396_market'](farms, privates, obs['market'], q, cfg, own)
                    if result[2:] != base[2:] or result[0] < base[0] or result[1] < base[1]:
                        break
                    deltas.append(result[1]-base[1])
                if len(deltas) != len(contexts):
                    continue
                quality = (min(deltas), sum(deltas))
                proposed = dict(action, market=candidate)
                if quality > best and g['_c414_accept'](obs, action, proposed, predicted, cfg):
                    best, selected = quality, proposed
    finally:
        g['_C414_REPORT'].clear()
        g['_C414_REPORT'].update(saved_report)
    return selected


def _c465_choose(g, obs, action, predicted, cfg):
    moved = _c465_empty_choose(g, obs, action, predicted, cfg)
    result = _c461_choose(g, obs, moved, predicted, cfg)
    if result == action: return action
    saved = dict(_C414_REPORT)
    try:
        return result if _c414_accept(obs, action, result, predicted, cfg) else action
    finally:
        _C414_REPORT.clear(); _C414_REPORT.update(saved)

_C465_RESPONSE = _c396_response
def _c465_response(obs, action, predicted, cfg):
    baseline = _C465_RESPONSE(obs, action, predicted, cfg)
    result = _c465_choose(globals(), obs, baseline, predicted, cfg)
    if result != baseline: _C465_REPORT['offers'] += 1
    return result
if _C465_ENABLED: _c396_response = _c465_response
_C465_ENTRY = agent
_C465_TELEMETRY = {}
def agent(observation, configuration=None):
    if int(observation['step']) == 0: _C465_REPORT['offers'] = 0
    result = _C465_ENTRY(observation, configuration)
    _C465_TELEMETRY.clear()
    _C465_TELEMETRY.update(getattr(_C465_ENTRY, 'telemetry', {}))
    _C465_TELEMETRY.update({'c465_'+k:v for k,v in _C465_REPORT.items()})
    return result
agent.telemetry = _C465_TELEMETRY
c465_submission_agent = agent

