# c479, Taeyang/Codex 2026-09-27. Apache-2.0 derivative.
# Four-turn confidence helper from leoprovorov/four-turn-forecast-notebook-version-2;
# upstream credited Dmitrii Gluzdov's Herd-Safe Sale Window. Existing notices retained.
# Preserve c387's near-best forecasts and all immediate one/two-turn signals.
# Only new third/fourth-turn signals require three past hits and >=70% matching.
_C479_ENABLED = True
_C479_PARENT = agent
_C479_TELEMETRY = {}
if _C479_ENABLED:
    assert _C365_CA_NS['_v92_predict'].__code__.co_filename == '<c387-public-forecast-frontier>'
    exec(compile('_C479_WINDOW = 4\n_C479_STATS = dict(extension_signals=0,rejected_signals=0)\ndef _c479_quantity(ev,item,step,seen):\n    immediate=sum(ev.get((step+d,item),0) for d in (1,2))\n    if immediate>=_V92_P_K: return immediate\n    extended=sum(ev.get((step+d,item),0) for d in range(1,_C479_WINDOW+1))\n    if extended<_V92_P_K: return immediate\n    prior=[(t,i) for (t,i),q in ev.items() if step-240<=t<step-1 and i==item and q>=2]\n    hits=sum(any((t+d,i) in seen for d in (-1,0,1)) for t,i in prior)\n    if hits>=3 and hits>=0.7*len(prior):\n        _C479_STATS[\'extension_signals\']+=1\n        return extended\n    _C479_STATS[\'rejected_signals\']+=1\n    return immediate\n\ndef _v92_predict(obs, action, st):\n    step = int(obs["step"])\n    _v92_p_update(obs, st)\n    if step < 150 or step >= 700:\n        return action\n    if step % _V92_P_EVERY == 0 or "best" not in st:\n        st["best"] = _v92_p_forecast(obs, st)\n    best = st["best"]\n    if not best:\n        return action\n    native = _IMPL.chassis.players.get(int(obs["player"]))\n    if not native or native.get("route") not in _IMPL.chassis.routes:\n        return action\n    tape = _IMPL.chassis.routes[native["route"]]\n    market = [list(o) for o in action.get("market") or []]\n    already = {o[1] for o in market if len(o) > 1 and o[0] in ("SELL", "BUY_PRODUCT")}\n    stock = projected_shed(action, FarmView(obs))\n    changed = False\n    for i, item in enumerate(_V92_P_ITEMS):\n        if item not in _V92_P_USE or item in already or len(market) >= MAX_ORDERS:\n            continue\n        votes = sum(1 for ev in best if _c479_quantity(ev, i, step, st["obs"]) >= _V92_P_K)\n        if votes < 1:\n            continue\n        alternate = not (best[0].get((step + 1, i), 0) + best[0].get((step + 2, i), 0) >= _V92_P_K)\n        ours = 0\n        for t in range(step + 1, min(len(tape), step + _V92_P_H + 1)):\n            ours += sum(min(100, int(o[2])) for o in (tape[t] or {}).get("market") or []\n                        if len(o) >= 3 and o[0] == "SELL" and o[1] == item)\n        qty = min(int(stock.get(item, 0)), ours)\n        if qty > 0:\n            market.insert(0, ["SELL", item, qty])\n            _V92_P_REPORT["pred_units"] += qty\n            _V92_P_REPORT["pred_fires"] += 1\n            if alternate:\n                _V92_P_REPORT["frontier_fires"] = _V92_P_REPORT.get("frontier_fires", 0) + 1\n                _V92_P_REPORT["frontier_units"] = _V92_P_REPORT.get("frontier_units", 0) + qty\n            changed = True\n    if not changed:\n        return action\n    result = dict(action)\n    result["market"] = market[:MAX_ORDERS]\n    return result\n', '<c479-confidence-four-turn>', 'exec'), _C365_CA_NS)

def agent(observation, configuration=None):
    if int(observation['step']) == 0 and _C479_ENABLED:
        _C365_CA_NS['_C479_STATS'].update(extension_signals=0,rejected_signals=0)
    result = _C479_PARENT(observation, configuration)
    _C479_TELEMETRY.clear()
    _C479_TELEMETRY.update(getattr(_C479_PARENT, 'telemetry', {}))
    if _C479_ENABLED:
        _C479_TELEMETRY.update({'c479_'+k:v for k,v in _C365_CA_NS['_C479_STATS'].items()})
    return result

agent.telemetry = _C479_TELEMETRY
c479_submission_agent = agent

# c493, Codex/Taeyang, 2026-09-27. Apache-2.0 derivative; notices retained.
# One existing complete route123 for the ICE/PIZZA pair in either order.
# Coherent raw cow/feed/harvest/place calendar; no future shops or opponent IDs.
_C493_ENABLED = True
_C493_PARENT = agent
_C493_ROUTER = _C358_IMPL.chassis.router
_C493_MAP = {('ICE_CREAM_SHOP', 'PIZZA_SHOP'): 123, ('PIZZA_SHOP', 'ICE_CREAM_SHOP'): 123}
_C493_TRACE = {}
_C493_TELEMETRY = {}

def _c493_router(obs, step, state):
    first = step >= 144 and not state.get('day6')
    route = _C493_ROUTER(obs, step, state)
    if first:
        shops = tuple((obs.get('town', {}).get('unlocked_shops', []) or [])[:2])
        target = _C493_MAP.get(shops, route) if _C493_ENABLED else route
        _C493_TRACE.update(parent_route=route, selected_route=target,
                          switch_step=step, shops=shops, triggered=target != route)
        state['route'] = route = target
    return route

_C358_IMPL.chassis.router = _c493_router

def agent(observation, configuration=None):
    if int(observation['step']) == 0:
        _C493_TRACE.clear()
    result = _C493_PARENT(observation, configuration)
    _C493_TELEMETRY.clear()
    _C493_TELEMETRY.update(getattr(_C493_PARENT, 'telemetry', {}))
    _C493_TELEMETRY.update({'c493_'+k:v for k,v in _C493_TRACE.items()})
    return result

agent.telemetry = _C493_TELEMETRY
c493_submission_agent = agent

# c506: public shadow coverage expansion. Taeyang/Codex 2026-09-23.
# Adds reviewed public sources 351; all embedded original source notices are retained.
# Only the hypothesis set changes. Source IDs below are internal dictionary
# keys, never a runtime opponent identifier or an input from Kaggle.
