# c516: earliest full wool deposit subject to collecting all three sites'
# fertilizer before midnight. Preserve original feed/care/harvest ordering.
# Midnight automatically banks carried goods from any worker position.
import itertools as _c516_itertools
_C516_ENABLED = True
_C516_PARENT = agent
_C516_NS = _C365_CA_NS
_C516_WORKER = _C516_NS['_SL_WORKER']
_C516_ACTIVE = {}
_C516_REPORT = dict(checks=0, changed=0, declined=0, active_declined=0, errors=0)
_C516_TELEMETRY = {}

def _c516_distance(a, b):
    return abs(a[0]-b[0])+abs(a[1]-b[1])

def _c516_tail(pos, tiles, targets, wool, hour):
    tasks = [(tuple(p), 'fert') for p,t in zip(targets,tiles) if t.get('fertilizer_available',0)]
    if wool:
        tasks.append((None, 'wool'))
    best = None
    for order in _c516_itertools.permutations(tasks):
        for home in ((4,4),(5,4),(4,5),(5,5)) if wool else (None,):
            cursor = pos; finish = hour; deposit = hour; resolved = []
            for target, kind in order:
                target = home if kind == 'wool' else target
                finish += _c516_distance(cursor,target)+1
                if kind == 'wool':
                    deposit = finish-1
                resolved.append((target,kind)); cursor = target
            if finish > 24:
                continue
            # Tie-break by total work and deterministic task order, never prices
            # or opponent information. All collected fertilizer is preserved.
            key = (deposit,finish,tuple(resolved))
            if best is None or key < best[0]:
                best = (key,resolved)
    return best

def _c516_worker(obs, actor, targets):
    old = _C516_WORKER(obs,actor,targets)
    day,hour = divmod(int(obs['step']),24)
    if not _C516_ENABLED or len(targets)!=3 or not 12<=day<28:
        return old
    seat = int(obs['player']); farm=obs['farms'][seat]; private=obs['private']
    if not 0<actor<=len(farm['hands']) or actor>=len(private['inventories']):
        return old
    tiles=[farm['tiles'][y][x] for x,y in targets]
    if not all(isinstance(t,dict) and t.get('animal')=='SHEEP' for t in tiles):
        return old
    inv=private['inventories'][actor]; pos=tuple(farm['hands'][actor-1])
    key=(seat,actor); active=_C516_ACTIVE.get(key)==day
    if not (active or inv.get('WOOL',0) or any(t.get('yield_units',0) for t in tiles)):
        return old
    hungry=sum(not t.get('fed_today') for t in tiles)
    if int(inv.get('WHEAT',0))<hungry:
        return old
    # Simulate only remaining own essential tasks in the unchanged nearest-site
    # order. Fertilizer is handled by the bounded tail planner, after essential
    # work unless moving it before wool deposit is required to finish the day.
    remaining=[]
    for i,(target,t) in enumerate(zip(targets,tiles)):
        commands=[]
        if not t.get('fed_today'):commands.append(['FEED'])
        if not t.get('cared_today'):commands.append(['CARE'])
        if t.get('yield_units',0):commands.append(['HARVEST'])
        if commands:remaining.append((i,tuple(target),commands))
    cursor=pos; end=hour; first=None
    while remaining:
        job=min(remaining,key=lambda z:(_c516_distance(cursor,z[1]),z[0]))
        remaining.remove(job)
        if first is None:first=(job[1],job[2][0])
        end+=_c516_distance(cursor,job[1])+len(job[2]);cursor=job[1]
    wool=int(inv.get('WOOL',0))+sum(int(t.get('yield_units',0)) for t in tiles)
    plan=_c516_tail(cursor,tiles,targets,wool,end)
    _C516_REPORT['checks']+=1
    if plan is None:
        _C516_REPORT['declined']+=1
        _C516_REPORT['active_declined']+=int(active)
        return old
    _C516_ACTIVE[key]=day
    walk=_C516_NS['_v219_walk']
    if first is not None:
        new=walk(pos,first[0]) or first[1]
    elif plan[1]:
        target,kind=plan[1][0]
        command=['PLACE','WOOL',int(inv.get('WOOL',0))] if kind=='wool' else ['COLLECT_FERTILIZER']
        new=walk(pos,target) or command
    else:
        new=old
    _C516_REPORT['changed']+=int(new!=old)
    return new

if _C516_ENABLED:
    _C516_NS['_SL_WORKER']=_c516_worker

def agent(observation, configuration=None):
    if int(observation['step'])==0:
        _C516_ACTIVE.clear()
        for key in _C516_REPORT:_C516_REPORT[key]=0
    result=_C516_PARENT(observation,configuration)
    _C516_TELEMETRY.clear()
    _C516_TELEMETRY.update(getattr(_C516_PARENT,'telemetry',{}))
    _C516_TELEMETRY.update({'c516_'+k:v for k,v in _C516_REPORT.items()})
    return result

agent.telemetry=_C516_TELEMETRY
c516_submission_agent=agent

# c519: preserve observed next native fertilizer pickups before forecasts.
import copy as _c519_copy
_C519_ENABLED = True
_C519_ENTRY = agent
_C519_PRE = _C405_PARENT
_C519_ACCESS = ((4,4),(5,4),(4,5),(5,5))
_C519_REPORT = dict(windows=0,changed=0,held=0,errors=0)
_C519_EVENTS = []
_C519_TELEMETRY = {}
def _c519_units(a):return [a.get('farmer') or ['PASS'],*(a.get('hands') or [])]

def _c519_qty(c):return max(0,int(c[2]) if len(c)>2 else 1)

def _c519_reserve(ns,obs,action):
 t=int(obs['step']);s=int(obs['player']);orders=_c519_copy.deepcopy(action.get('market') or [])
 if not 144<=t<695 or t%24==23 or len(orders)>10:return None,None
 native=ns['_IMPL'].chassis.players[s];tape=ns['_IMPL'].chassis.routes[2 if t+1>=648 else native['route']]
 commands=_c519_units(tape[t+1]);farm,private=ns['_ov_fields'](obs,action);positions=[tuple(farm['farmer']),*map(tuple,farm['hands'])]
 for order in orders:
  if order and order[0]=='HIRE':positions.append(min(_C519_ACCESS,key=lambda p:(positions.count(p),_C519_ACCESS.index(p))))
 need=sum(_c519_qty(c) for pos,c in zip(positions,commands) if pos in _C519_ACCESS and c[:2]==['PICKUP','FERTILIZER'])
 if not need:return None,None
 stock,buys,sales=ns['_r97_market_stock'](private['shed'],orders)
 context=dict(need=need,before_fields_fert=obs['private']['shed'].get('FERTILIZER',0),after_fields_fert=private['shed'].get('FERTILIZER',0),original_final_fert=stock.get('FERTILIZER',0),orders_before=orders,orders_after=orders,held=0)
 if stock.get('FERTILIZER',0)>=need:return None,context
 if not ns['_r97_budget'](obs,orders):context['declined']='original_budget';return None,context
 trial=_c519_copy.deepcopy(orders);held=0
 for i in range(len(trial)-1,-1,-1):
  if trial[i][:2]!=['SELL','FERTILIZER']:continue
  while len(trial[i])>=3 and trial[i][2]>0:
   before,_,bsales=ns['_r97_market_stock'](private['shed'],trial)
   if before.get('FERTILIZER',0)>=need:break
   q=_c519_copy.deepcopy(trial);q[i][2]-=1;after,ab,ass=ns['_r97_market_stock'](private['shed'],q)
   if after.get('FERTILIZER',0)<=before.get('FERTILIZER',0):break
   if any(ab.get(k,0)<v for k,v in buys.items()) or any(after.get(k,0)!=v for k,v in stock.items() if k!='FERTILIZER'):break
   if any(ass.get(k,0)!=v for k,v in sales.items() if orders[k][:2]!=['SELL','FERTILIZER']):break
   if not ns['_r97_budget'](obs,q):break
   trial=q;held+=1
 final,_,_=ns['_r97_market_stock'](private['shed'],trial)
 context.update(orders_after=trial,held=held,proposed_final_fert=final.get('FERTILIZER',0),reserve_met=final.get('FERTILIZER',0)>=need)
 return (dict(action,market=trial) if held and context['reserve_met'] else None),context

def _c519_pre(observation,configuration=None):
    action=_C519_PRE(observation,configuration)
    if not _C519_ENABLED:
        return action
    try:
        trial,context=_c519_reserve(_C365_CA_NS,observation,action)
        if context is not None:
            _C519_REPORT['windows']+=1
        if trial is not None:
            _C519_REPORT['changed']+=1
            _C519_REPORT['held']+=context['held']
            _C519_EVENTS.append(dict(step=int(observation['step']),**context))
            return trial
    except Exception:
        _C519_REPORT['errors']+=1
    return action

if _C519_ENABLED:
    _C405_PARENT=_c519_pre

def agent(observation,configuration=None):
    if int(observation['step'])==0:
        _C519_EVENTS.clear()
        for key in _C519_REPORT:_C519_REPORT[key]=0
    result=_C519_ENTRY(observation,configuration)
    _C519_TELEMETRY.clear()
    _C519_TELEMETRY.update(getattr(_C519_ENTRY,'telemetry',{}))
    _C519_TELEMETRY.update({'c519_'+k:v for k,v in _C519_REPORT.items()})
    return result

agent.telemetry=_C519_TELEMETRY
c519_submission_agent=agent

# c520: only already-committed sheep service may use verified sale-freed space.
_C520_ENABLED = True
_C520_ENTRY = agent
_C520_NS = _C365_CA_NS
_C520_OLD = _C520_NS['_SL_REQUEST']
_C520_REPORT = dict(checks=0,allowed=0,declined=0,errors=0)
_C520_EVENTS = []
_C520_TELEMETRY = {}

def _c520_allow_capacity(obs,action,stock,extra,initial):
    if initial or not 12<=int(obs['step'])//24<28:
        return False
    _C520_REPORT['checks']+=1
    try:
        original=list(action.get('market') or [])
        orders=original+extra
        final,buys,sales=_C520_NS['_r97_market_stock'](stock,orders)
        valid=(len(orders)<=10 and all(buys.get(i,0)==max(0,int(o[2])) for i,o in enumerate(orders) if len(o)>2 and o[0] in ('BUY_PRODUCT','BUY_ANIMAL')) and _C520_NS['_r97_budget'](obs,orders))
        if valid:
            _C520_REPORT['allowed']+=1
            _C520_EVENTS.append(dict(step=int(obs['step']),stock_before=dict(stock),orders_before=original,extra=extra,proposed_stock=final,buys=buys,sales=sales))
            return True
        _C520_REPORT['declined']+=1
    except Exception:
        _C520_REPORT['errors']+=1
    return False

_C520_REQUEST_SOURCE = "def _c520_capacity_request(obs,action,state,native):\n    step=int(obs['step']);day=step//24;hour=step%24\n    # EXP242: preserve native indices while servicing already committed sheep.\n    if state.get('requested_day')==day:return action\n    committed=state.get('committed')\n    if not committed and (hour>(3 if day==11 else 1) or day not in (11,12) or not _v233_eligible(obs,native)):return action\n    planned=_v219_native_day(native,day)\n    deadline=2 if committed else (3 if day==11 else 1)\n    if committed:\n        last_native_hire=max((h for h,a in enumerate(planned) if any(o and o[0]=='HIRE' for o in a.get('market',[]))),default=0)\n        if 2<last_native_hire<=6:deadline=6\n    if hour>deadline:return action\n    if any(o and o[0]=='HIRE' for a in planned[hour+1:] for o in a.get('market',[])):return action\n    farm=obs['farms'][obs['player']];market=action.get('market',[])\n    parent_hires=sum(bool(o) and o[0]=='HIRE' for o in market)\n    expected=max(len(a.get('hands',[])) for a in planned)\n    if len(farm['hands'])+parent_hires!=expected:return action\n    initial=not state.get('committed')\n    extra=([['BUY_LAND'],['BUY_ANIMAL','SHEEP',6]] if initial else [])+[['BUY_PRODUCT','WHEAT',6],['HIRE'],['HIRE']]\n    if len(market)+len(extra)>MAX_ORDERS:return action\n    stock=projected_shed(action,FarmView(obs))\n    incoming=6+6*initial\n    budget=7000*initial+6*(int(obs['market']['prices']['WHEAT'])+10)\n    budget+=sum(_v219_fib(n) for n in range(farm['hires_today'],farm['hires_today']+parent_hires+2))\n    for o in market:\n        if not o:continue\n        if o[0]=='BUY_LAND':return action\n        if o[0]=='BUY_PRODUCT':\n            incoming+=int(o[2]);budget+=int(o[2])*(int(obs['market']['prices'][o[1]])+10)\n        elif o[0]=='BUY_ANIMAL':\n            incoming+=int(o[2]);budget+=int(o[2])*{'SHEEP':500,'COW':400,'GOOSE':300}[o[1]]\n        elif o[0]=='BUY_SEED':budget+=int(o[2])*{'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}[o[1]]\n    if sum(stock.values())+incoming>100 and not _c520_allow_capacity(obs,action,stock,extra,initial):\n        _V233_REPORT['sheep_capacity_declines']+=1;return action\n    if farm['money']<budget+(3000 if initial else 1000):\n        _V233_REPORT['sheep_budget_declines']+=1;return action\n    state['requested_day']=day\n    state['pending']={'first':expected+1,'initial':initial}\n    _V233_REPORT['sheep_hire_requests']+=2;_V233_REPORT['sheep_feed_buy_requests']+=6\n    if initial:_V233_REPORT['sheep_commit_requests']+=1\n    result=copy.deepcopy(action);result['market']=market+extra\n    return result"
if _C520_ENABLED:
    _C520_NS['_c520_allow_capacity']=_c520_allow_capacity
    exec(compile(_C520_REQUEST_SOURCE,'<c520_capacity_request>','exec'),_C520_NS)
    _C520_NS['_SL_REQUEST']=_C520_NS['_c520_capacity_request']

def agent(observation,configuration=None):
    if int(observation['step'])==0:
        _C520_EVENTS.clear()
        for key in _C520_REPORT:_C520_REPORT[key]=0
    result=_C520_ENTRY(observation,configuration)
    _C520_TELEMETRY.clear()
    _C520_TELEMETRY.update(getattr(_C520_ENTRY,'telemetry',{}))
    _C520_TELEMETRY.update({'c520_'+k:v for k,v in _C520_REPORT.items()})
    return result

agent.telemetry=_C520_TELEMETRY
c520_submission_agent=agent

