# c536: diagnostic KEEP arm only; no adoption authority.
_C536_KEEP_TOMATO = True
_C536_NS = _C365_CA_NS
_C536_ORIGINAL_QUALIFY = _C536_NS['_v219_qualifies']
_C536_REPORT = {'declines': 0, 'features': []}
def _c536_qualify(obs, native):
    qualified = _C536_ORIGINAL_QUALIFY(obs, native)
    if _C536_KEEP_TOMATO and qualified:
        _C536_REPORT['declines'] += 1
        if len(_C536_REPORT['features']) < 40:
            _C536_REPORT['features'].append(dict(step=int(obs['step']), player=int(obs['player']), money=obs['farms'][int(obs['player'])]['money'], prices=dict(obs['market']['prices']), shops=list(obs['town']['unlocked_shops'])))
        return False
    return qualified
_C536_NS['_v219_qualifies'] = _c536_qualify
_C536_ENTRY = agent
def agent(observation, configuration=None):
    if int(observation['step']) == 0:
        _C536_REPORT['declines'] = 0
        _C536_REPORT['features'].clear()
    return _C536_ENTRY(observation, configuration)
agent.telemetry = _C536_ENTRY.telemetry
